// Data models for destinations discovered via the places data provider.

/// Represents a destination discovered from OSM/travel data sources.
class Destination {
  /// Stable place ID from the data source (e.g., OSM node ID).
  final String sourceId;

  /// Human-readable place name.
  final String name;

  /// Description from the data source or AI-generated (flagged accordingly).
  final String description;

  /// Whether the description was generated by AI vs sourced from data provider.
  final bool isDescriptionAIGenerated;

  /// Latitude coordinate.
  final double latitude;

  /// Longitude coordinate.
  final double longitude;

  /// Address or region text.
  final String region;

  /// Category tags from the data source.
  final List<String> categories;

  /// URL to the source page (e.g., OSM, Wikipedia).
  final String sourceUrl;

  /// Image URL (when legally available from open data).
  final String imageUrl;

  /// Opening hours string when available.
  final String? openingHours;

  /// ISO 8601 timestamp of when this data was retrieved.
  final String retrievedAt;

  /// Source attribution text (e.g., "© OpenStreetMap contributors").
  final String attribution;

  /// AI-generated match score (0.0 to 1.0) based on user interests.
  final double relevanceScore;

  const Destination({
    required this.sourceId,
    required this.name,
    this.description = '',
    this.isDescriptionAIGenerated = false,
    required this.latitude,
    required this.longitude,
    this.region = '',
    this.categories = const [],
    this.sourceUrl = '',
    this.imageUrl = '',
    this.openingHours,
    this.retrievedAt = '',
    this.attribution = '© OpenStreetMap contributors',
    this.relevanceScore = 0.0,
  });

  factory Destination.fromJson(Map<String, dynamic> json) {
    return Destination(
      sourceId: json['sourceId'] as String? ?? '',
      name: json['name'] as String? ?? 'Unknown Place',
      description: json['description'] as String? ?? '',
      isDescriptionAIGenerated: json['isDescriptionAIGenerated'] as bool? ?? false,
      latitude: (json['latitude'] as num?)?.toDouble() ?? 0.0,
      longitude: (json['longitude'] as num?)?.toDouble() ?? 0.0,
      region: json['region'] as String? ?? '',
      categories: (json['categories'] as List<dynamic>?)
              ?.map((e) => e.toString())
              .toList() ??
          [],
      sourceUrl: json['sourceUrl'] as String? ?? '',
      imageUrl: json['imageUrl'] as String? ?? '',
      openingHours: json['openingHours'] as String?,
      retrievedAt: json['retrievedAt'] as String? ?? '',
      attribution: json['attribution'] as String? ?? '© OpenStreetMap contributors',
      relevanceScore: (json['relevanceScore'] as num?)?.toDouble() ?? 0.0,
    );
  }

  Map<String, dynamic> toJson() {
    return {
      'sourceId': sourceId,
      'name': name,
      'description': description,
      'isDescriptionAIGenerated': isDescriptionAIGenerated,
      'latitude': latitude,
      'longitude': longitude,
      'region': region,
      'categories': categories,
      'sourceUrl': sourceUrl,
      'imageUrl': imageUrl,
      if (openingHours != null) 'openingHours': openingHours,
      'retrievedAt': retrievedAt,
      'attribution': attribution,
      'relevanceScore': relevanceScore,
    };
  }
}
